def fewestItemsForTarget(nums, target):
    INF = float("inf")
    best = [INF] * (target + 1)
    best[0] = 0
    for x in nums:
        for s in range(target, x - 1, -1):
            if best[s - x] + 1 < best[s]:
                best[s] = best[s - x] + 1
    return -1 if best[target] == INF else best[target]
